import scrollLock from 'scroll-lock';
import { disablePageScroll, enablePageScroll } from 'scroll-lock/dist/scroll-lock.js';

export function initListOfServices() {
  const lists =  document.querySelectorAll('[data-list]');
  const btnsOpenList = document.querySelectorAll('[data-open-list]');

  btnsOpenList.forEach(btn => {
    btn.addEventListener('click', (e) => {
      const button = e.currentTarget;
      const dataValue = button.getAttribute('data-open-list');
      const listShowed = document.querySelector(`[data-list="${dataValue}"]`)

      if (listShowed) {
        if (button.classList.contains('screen4__btn-info')) {
          e.stopPropagation();
        }
        listShowed.classList.add('active');
        disablePageScroll(listShowed);
      }
    })

  })

  lists.forEach(list => {
    list.addEventListener('click', (e) => {
      if (e.target.closest('.cross')) {
        list.classList.remove('active');
        enablePageScroll();
      }
    })
  })
}